private TreeNode<T> rotateRight(TreeNode<T> node) {
    TreeNode<T> leftChild = node.getLeft();
    TreeNode<T> rightOfLeftChild = leftChild.getRight();

    leftChild.setRight(node);
    node.setLeft(rightOfLeftChild);

    node.updateHeight();
    leftChild.updateHeight();

    return leftChild;
}

