    int day = (int) (timeBucket % 100);
    int month = (int) ((timeBucket / 100) % 100);
    int year = (int) (timeBucket / 10000);
    int startDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000 + month * 100 + startDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 10000);
    int monthDay = (int) (timeBucket % 10000);
    int day = monthDay % 100;
    int month = (monthDay / 100) % 100;
    int monthDays = 0;

    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            monthDays = 31;
            break;
        case 4: case 6: case 9: case 11:
            monthDays = 30;
            break;
        case 2:
            if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
                monthDays = 29;
            } else {
                monthDays = 28;
            }
            break;
    }

    day = (day - 1) / dayStep * dayStep + 1;
    if (day > monthDays) {
        day = monthDays;
    }

    return year * 10000 + month * 100 + day;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    int dayOfMonth = (int) (timeBucket % 100);
    int month = (int) ((timeBucket / 100) % 100);
    int year = (int) (timeBucket / 10000);

    int baseDay = 1 + ((dayOfMonth - 1) / dayStep) * dayStep;
    return year * 10000 + month * 100 + baseDay;
}

