LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            lb = ensureCapacity(lb, 1);
            lb.buffer[lb.offset++] = (byte) c;
        } else if (c < 0x800) {
            lb = ensureCapacity(lb, 2);
            lb.buffer[lb.offset++] = (byte) (0xc0 | (c >> 6));
            lb.buffer[lb.offset++] = (byte) (0x80 | (c & 0x3f));
        } else if (c < 0xd800 || c > 0xdfff) {
            lb = ensureCapacity(lb, 3);
            lb.buffer[lb.offset++] = (byte) (0xe0 | (c >> 12));
            lb.buffer[lb.offset++] = (byte) (0x80 | ((c >> 6) & 0x3f));
            lb.buffer[lb.offset++] = (byte) (0x80 | (c & 0x3f));
        } else {
            i++;
            if (i >= str.length()) {
                throw new IllegalArgumentException("invalid utf-8");
            }
            char c2 = str.charAt(i);
            int codePoint = Character.toCodePoint(c, c2);
            lb = ensureCapacity(lb, 4);
            lb.buffer[lb.offset++] = (byte) (0xf0 | (codePoint >> 18));
            lb.buffer[lb.offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3f));
            lb.buffer[lb.offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3f));
            lb.buffer[lb.offset++] = (byte) (0x80 | (codePoint & 0x3f));
        }
    }
    return lb;
}

LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int len = str.length();
    byte[] utf8Bytes = new byte[len * 3]; // Maximum UTF-8 length
    int charCount = 0;
    int byteCount = 0;

    for (int i = 0; i < len; i++) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            utf8Bytes[byteCount++] = (byte) ch;
        } else if (ch < 0x800) {
            utf8Bytes[byteCount++] = (byte) (0xc0 | (ch >> 6));
            utf8Bytes[byteCount++] = (byte) (0x80 | (ch & 0x3f));
        } else if (Character.isSurrogate(ch)) {
            char low = str.charAt(++i);
            int codePoint = Character.toCodePoint(ch, low);
            utf8Bytes[byteCount++] = (byte) (0xf0 | (codePoint >> 18));
            utf8Bytes[byteCount++] = (byte) (0x80 | ((codePoint >> 12) & 0x3f));
            utf8Bytes[byteCount++] = (byte) (0x80 | ((codePoint >> 6) & 0x3f));
            utf8Bytes[byteCount++] = (byte) (0x80 | (codePoint & 0x3f));
        } else {
            utf8Bytes[byteCount++] = (byte) (0xe0 | (ch >> 12));
            utf8Bytes[byteCount++] = (byte) (0x80 | ((ch >> 6) & 0x3f));
            utf8Bytes[byteCount++] = (byte) (0x80 | (ch & 0x3f));
        }
        charCount++;
    }

    byte[] trimmedBytes = Arrays.copyOf(utf8Bytes, byteCount);
    return WriteUtils.writeBytes(trimmedBytes, session, lb);
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        return lb;
    }
    final int length = str.length();
    int utf8Length = 0;
    for (int i = 0; i < length; i++) {
        final char ch = str.charAt(i);
        if (ch <= 0x007F) {
            utf8Length++;
        } else if (ch <= 0x07FF) {
            utf8Length += 2;
        } else {
            if (Character.isSurrogate(ch)) {
                if (i + 1 < length) {
                    final char low = str.charAt(++i);
                    if (Character.isSurrogatePair(ch, low)) {
                        utf8Length += 4;
                        continue;
                    }
                }
                throw new IllegalArgumentException("Invalid UTF-16 sequence.");
            }
            utf8Length += 3;
        }
    }
    lb = allocateBuffer(utf8Length, lb);
    final byte[] buffer = lb.buffer;
    int offset = lb.offset;
    for (int i = 0; i < length; i++) {
        final char ch = str.charAt(i);
        if (ch <= 0x007F) {
            buffer[offset++] = (byte) ch;
        } else if (ch <= 0x07FF) {
            buffer[offset++] = (byte) (0xC0 | (ch >> 6));
            buffer[offset++] = (byte) (0x80 | (ch & 0x3F));
        } else {
            if (Character.isSurrogate(ch)) {
                if (i + 1 < length) {
                    final char low = str.charAt(++i);
                    if (Character.isSurrogatePair(ch, low)) {
                        final int codePoint = Character.toCodePoint(ch, low);
                        buffer[offset++] = (byte) (0xF0 | (codePoint >> 18));
                        buffer[offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
                        buffer[offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
                        buffer[offset++] = (byte) (0x80 | (codePoint & 0x3F));
                        continue;
                    }
                }
                throw new IllegalArgumentException("Invalid UTF-16 sequence.");
            }
            buffer[offset++] = (byte) (0xE0 | (ch >> 12));
            buffer[offset++] = (byte) (0x80 | ((ch >> 6) & 0x3F));
            buffer[offset++] = (byte) (0x80 | (ch & 0x3F));
        }
    }
    lb.offset = offset;
    return lb;
}

