private void pop(final String descriptor){
    // Assuming the descriptor is a method descriptor, we need to parse it to get the argument types
    if (descriptor.charAt(0) == '(') {
        int end = descriptor.indexOf(')');
        String argTypes = descriptor.substring(1, end);
        int index = 0;
        while (index < argTypes.length()) {
            char c = argTypes.charAt(index);
            switch (c) {
                case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                    // These are all single-slot types
                    index++;
                    break;
                case 'D': case 'J':
                    // These are double-slot types
                    index += 2;
                    break;
                case 'L':
                    // Object type, find the end of it
                    index = argTypes.indexOf(';', index) + 1;
                    break;
                case '[':
                    // Array type, skip to the end of it
                    while (index < argTypes.length() && argTypes.charAt(index) == '[') {
                        index++;
                    }
                    if (index >= argTypes.length()) {
                        // Malformed descriptor, possibly just array brackets
                        break;
                    }
                    c = argTypes.charAt(index);
                    if (c == 'L') {
                        // Object type within array, find the end of it
                        index = argTypes.indexOf(';', index) + 1;
                    } else {
                        // Primitive type within array
                        index++;
                    }
                    break;
                default:
                    // Malformed descriptor
                    index++;
                    break;
            }
        }
    } else {
        // Assuming descriptor is a single type, pop accordingly
        char c = descriptor.charAt(0);
        switch (c) {
            case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                // Single-slot types
                break;
            case 'D': case 'J':
                // Double-slot types
                break;
            case 'L':
                // Object type
                break;
            case '[':
                // Array type, we would need to parse further but for simplicity, treat as single-slot
                break;
            default:
                // Malformed descriptor
                break;
        }
    }
}

