    if (descriptor.charAt(0) == '(') {
        int current = 1; // Start after the '('
        while (descriptor.charAt(current) != ')') {
            char type = descriptor.charAt(current);
            switch (type) {
                case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                    // These are all single-slot types
                    popSingleSlot();
                    current++;
                    break;
                case 'D': case 'J':
                    // These are double-slot types
                    popDoubleSlot();
                    current++;
                    break;
                case 'L':
                    // Object type, read until ';'
                    while (descriptor.charAt(current) != ';') {
                        current++;
                    }
                    popSingleSlot(); // Objects are single-slot
                    current++; // Move past ';'
                    break;
                case '[':
                    // Array type, skip to the element type and treat it as a single-slot
                    while (descriptor.charAt(current) == '[') {
                        current++;
                    }
                    // The next character could be 'L' (object type) or a primitive type character
