                    popSingleSlot(); // Arrays are single-slot
                    current++; // Move past the last character of the descriptor
                    break;
                default:
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
        }
    } else {
        // If it's not a method descriptor, assume it's a field descriptor and pop based on type
        switch (descriptor.charAt(0)) {
            case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                popSingleSlot();
                break;
            case 'D': case 'J':
                popDoubleSlot();
                break;
            case 'L':
                while (descriptor.charAt(current) != ';') {
                    current++;
                }
                popSingleSlot();
                break;
            case '[':
                while (descriptor.charAt(current) == '[') {
                    current++;
                }
                if (descriptor.charAt(current) == 'L') {
                    while (descriptor.charAt(current) != ';') {
                        current++;
                    }
                }
                popSingleSlot();
                break;
            default:
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
    }
}

